export type IconName = keyof typeof ICON_PATHS;
export type IconWeight = "outline" | "filled";

const Icon = forwardRef<
  SVGSVGElement,
  {
    name: IconName;
    size?: number;
    className?: string;
    color?: string;
    weight?: IconWeight;
  }
>(({ name, size = 20, className, color, weight = "outline" }, ref) => {
  const entry = ICON_PATHS[name];
  if (!entry) return null;
  const html = weight === "filled" ? entry.F : entry.O;
  return (
    <svg
      ref={ref}
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      className={className}
      style={color != null ? { color } : undefined}
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
});

Icon.displayName = "Icon";

export default Icon;
